1	package com.example.starter.feed.service;
2	
3	import com.example.starter.feed.domain.AlertType;
4	import com.example.starter.feed.domain.BatchStatus;
5	import com.example.starter.feed.domain.FormulaStatus;
6	import com.example.starter.feed.dto.BatchCreateRequest;
7	import com.example.starter.feed.dto.BatchStatusResponse;
8	import com.example.starter.feed.dto.FeedingRecordRequest;
9	import com.example.starter.feed.dto.FeedingRecordResponse;
10	import com.example.starter.feed.dto.ProductionRequest;
11	import com.example.starter.feed.dto.ProductionResponse;
12	import com.example.starter.feed.dto.SlaughterRequest;
13	import com.example.starter.feed.dto.SlaughterResponse;
14	import com.example.starter.feed.repo.AlertRepository;
15	import com.example.starter.feed.repo.BatchRepository;
16	import com.example.starter.feed.repo.DictRepository;
17	import com.example.starter.feed.repo.FormulaRepository;
18	import com.example.starter.feed.repo.ProductionRepository;
19	import com.example.starter.feed.web.ApiException;
20	import org.springframework.dao.DuplicateKeyException;
21	import org.springframework.stereotype.Service;
22	import org.springframework.transaction.annotation.Transactional;
23	
24	import java.time.Clock;
25	import java.time.Instant;
26	import java.time.LocalDate;
27	import java.util.HashMap;
28	import java.util.List;
29	import java.util.Map;
30	import java.util.Optional;
31	
32	/**
33	 * 养殖批次：登记、含药配方投产与休药期合并、含药饲喂（含迟到告警）、出栏判定。
34	 */
35	@Service
36	public class BatchService {
37	
38	    /** 幂等请求类型：出栏申请。 */
39	    public static final String KIND_SLAUGHTER_APPLY = "SLAUGHTER_APPLY";
40	
41	    private final BatchRepository batchRepository;
42	    private final FormulaRepository formulaRepository;
43	    private final ProductionRepository productionRepository;
44	    private final DictRepository dictRepository;
45	    private final AlertRepository alertRepository;
46	    private final IdempotencyService idempotencyService;
47	    private final Clock clock;
48	
49	    public BatchService(BatchRepository batchRepository,
50	                        FormulaRepository formulaRepository,
51	                        ProductionRepository productionRepository,
52	                        DictRepository dictRepository,
53	                        AlertRepository alertRepository,
54	                        IdempotencyService idempotencyService,
55	                        Clock clock) {
56	        this.batchRepository = batchRepository;
57	        this.formulaRepository = formulaRepository;
58	        this.productionRepository = productionRepository;
59	        this.dictRepository = dictRepository;
60	        this.alertRepository = alertRepository;
61	        this.idempotencyService = idempotencyService;
62	        this.clock = clock;
63	    }
64	
65	    /**
66	     * 登记合成养殖批次。
67	     */
68	    @Transactional
69	    public BatchStatusResponse createBatch(BatchCreateRequest request) {
70	        try {
71	            batchRepository.insert(request.batchNo(), request.species());
72	        } catch (DuplicateKeyException e) {
73	            throw ApiException.conflict("养殖批次号已存在: " + request.batchNo());
74	        }
75	        return toStatusResponse(batchRepository.get(request.batchNo()));
76	    }
77	
78	    @Transactional(readOnly = true)
79	    public BatchStatusResponse getBatch(String batchNo) {
80	        return toStatusResponse(batchRepository.get(batchNo));
81	    }
82	
83	    /**
84	     * 含药（或无药）配方投产到批次：
85	     * 仅 APPROVED 版本可投产、种类须一致；含药配方写入批准版本药物快照并合并休药期。
86	     * 同批次并发投产两个含药配方时按行锁串行化，休药期取各药物最大休药天数与最晚末次饲喂。
87	     */
88	    @Transactional
89	    public ProductionResponse produce(ProductionRequest request) {
90	        FormulaRepository.FormulaRow formula =
91	                formulaRepository.get(request.formulaCode(), request.version());
92	        if (formula.status().equals(FormulaStatus.REJECTED.name())) {
93	            throw ApiException.unprocessable("合规拒绝的配方不可投产: "
94	                    + request.formulaCode() + " v" + request.version());
95	        }
96	        if (formula.status().equals(FormulaStatus.SUBMITTED.name())) {
97	            throw ApiException.unprocessable("配方尚未批准，不可投产: "
98	                    + request.formulaCode() + " v" + request.version());
99	        }
100	
101	        // 行锁串行化同一批次的并发投产/饲喂/出栏。
102	        BatchRepository.BatchRow batch = batchRepository.lockAndGet(request.batchNo());
103	        // 含药配方必须绑定目标动物种类（提交时已校验非空），投产时须与批次种类一致；无药配方不限制。
104	        if (formula.containsDrug() && !batch.species().equals(formula.targetSpecies())) {
105	            throw ApiException.unprocessable("配方目标动物种类 " + formula.targetSpecies()
106	                    + " 与批次种类 " + batch.species() + " 不一致，拒绝投产");
107	        }
108	        if (BatchStatus.SLAUGHTERED.name().equals(batch.status())) {
109	            throw ApiException.unprocessable("批次已出栏（终态），不可再投产: " + batch.batchNo());
110	        }
111	
112	        Instant producedAt = clock.instant();
113	        Optional<Long> productionIdOpt = productionRepository.insertProduction(
114	                batch.id(), formula.id(), formula.formulaCode(), formula.version(), producedAt);
115	        if (productionIdOpt.isEmpty()) {
116	            throw ApiException.conflict("该配方版本已投产到本批次，不可重复投产: "
117	                    + request.formulaCode() + " v" + request.version());
118	        }
119	        long productionId = productionIdOpt.get();
120	
121	        boolean wasInProduction = FormulaStatus.IN_PRODUCTION.name().equals(formula.status());
122	        if (!wasInProduction) {
123	            formulaRepository.markFirstProduced(formula.id(), producedAt);
124	        }
125	
126	        List<FormulaRepository.ComponentRow> drugRows =
127	                formulaRepository.findDrugs(formula.id());
128	        // 快照按投产时刻已批准版本内容冻结（含休药天数），后续版本修改不追溯减轻。
129	        Map<String, DictRepository.DrugDict> dict = new HashMap<>();
130	        for (FormulaRepository.ComponentRow d : drugRows) {
131	            DictRepository.DrugDict dObj = dictRepository.findDrug(d.code())
132	                    .orElseThrow(() -> ApiException.unprocessable("投产时药物字典缺失: " + d.code()));
133	            dict.put(d.code(), dObj);
134	            productionRepository.insertDrugSnapshot(productionId, d.code(), d.ratio(), dObj.withdrawalDays());
135	        }
136	
137	        if (!drugRows.isEmpty()) {
138	            // 投产即发生一次含药饲喂（末次饲喂时刻由请求给出）。
139	            long feedingId = productionRepository.insertFeeding(
140	                    batch.id(), productionId, formula.formulaCode(), formula.version(),
141	                    request.feedAtUtc(), false);
142	            for (FormulaRepository.ComponentRow d : drugRows) {
143	                productionRepository.insertFeedingDrug(feedingId, d.code(), dict.get(d.code()).withdrawalDays());
144	            }
145	        }
146	
147	        Merged merged = recomputeBatchWithdrawal(batch.id());
148	        batchRepository.updateWithdrawal(batch.id(),
149	                merged == null ? null : merged.latestFeed(),
150	                merged == null ? null : merged.untilDate(),
151	                merged == null ? null : merged.maxDays());
152	
153	        BatchRepository.BatchRow refreshed = batchRepository.get(request.batchNo());
154	        return new ProductionResponse(
155	                request.formulaCode(),
156	                request.version(),
157	                request.batchNo(),
158	                producedAt,
159	                refreshed.lastMedicatedFeedAtUtc(),
160	                refreshed.withdrawalUntilDate(),
161	                earliest(refreshed.withdrawalUntilDate()),
162	                refreshed.governingWithdrawalDays());
163	    }
164	
165	    /**
166	     * 登记一次含药饲喂事件（须已存在对应投产）；出栏后迟到则只记事件并告警。
167	     */
168	    @Transactional
169	    public FeedingRecordResponse recordFeeding(FeedingRecordRequest request) {
170	        FormulaRepository.FormulaRow formula =
171	                formulaRepository.get(request.formulaCode(), request.version());
172	        BatchRepository.BatchRow batch = batchRepository.lockAndGet(request.batchNo());
173	        ProductionRepository.ProductionRow production = productionRepository
174	                .findByBatchAndFormula(batch.id(), formula.id())
175	                .orElseThrow(() -> ApiException.unprocessable(
176	                        "该配方版本尚未投产到本批次，不能登记饲喂: "
177	                                + request.formulaCode() + " v" + request.version()));
178	        List<ProductionRepository.DrugSnapshotRow> snapshots =
179	                productionRepository.findSnapshots(production.id());
180	        if (snapshots.isEmpty()) {
181	            throw ApiException.unprocessable("该配方无药物添加剂，不属于含药饲喂: "
182	                    + request.formulaCode() + " v" + request.version());
183	        }
184	
185	        boolean late = BatchStatus.SLAUGHTERED.name().equals(batch.status());
186	        long feedingId = productionRepository.insertFeeding(
187	                batch.id(), production.id(), formula.formulaCode(), formula.version(),
188	                request.feedAtUtc(), late);
189	        for (ProductionRepository.DrugSnapshotRow s : snapshots) {
190	            productionRepository.insertFeedingDrug(feedingId, s.drugCode(), s.withdrawalDays());
191	        }
192	
193	        boolean alerted = false;
194	        if (late) {
195	            // 出栏终态不变；休药期字段也不因迟到饲喂而改变。
196	            alertRepository.insert(AlertType.LATE_MEDICATED_FEEDING.name(), batch.batchNo(), feedingId,
197	                    "批次已于 " + batch.slaughteredAtUtc() + " 出栏，出栏后收到迟到含药饲喂记录（时刻 "
198	                            + request.feedAtUtc() + "，配方 " + request.formulaCode()
199	                            + " v" + request.version() + "），仅记录事件并告警");
200	            alerted = true;
201	        } else {
202	            Merged merged = recomputeBatchWithdrawal(batch.id());
203	            batchRepository.updateWithdrawal(batch.id(),
204	                    merged == null ? null : merged.latestFeed(),
205	                    merged == null ? null : merged.untilDate(),
206	                    merged == null ? null : merged.maxDays());
207	        }
208	
209	        return new FeedingRecordResponse(request.batchNo(), request.formulaCode(), request.version(),
210	                request.feedAtUtc(), late, alerted);
211	    }
212	
213	    /**
214	     * 出栏申请（requestId 幂等）：休药期内拒绝并提示最早合法出栏时刻；
215	     * 重复出栏（终态）返回幂等成功；无休药义务的批次随时可出栏。
216	     */
217	    public IdempotencyService.Result<SlaughterResponse> applySlaughter(SlaughterRequest request) {
218	        IdempotencyService.Result<SlaughterResponse> result = idempotencyService.execute(
219	                request.requestId(),
220	                KIND_SLAUGHTER_APPLY,
221	                request,
222	                () -> doSlaughter(request),
223	                SlaughterResponse.class);
224	        if (result.replayed() && !result.response().replayed()) {
225	            SlaughterResponse r = result.response();
226	            return new IdempotencyService.Result<>(
227	                    new SlaughterResponse(r.batchNo(), r.approved(), true, r.status(),
228	                            r.earliestSlaughterUtc(), r.rejectReason(),
229	                            r.slaughteredAtUtc(), r.appliedAtUtc()),
230	                    result.httpStatus(), true);
231	        }
232	        return result;
233	    }
234	
235	    private IdempotencyService.Outcome doSlaughter(SlaughterRequest request) {
236	        BatchRepository.BatchRow batch = batchRepository.lockAndGet(request.batchNo());
237	        Instant earliest = earliest(batch.withdrawalUntilDate());
238	
239	        // 已出栏终态：重复出栏申请返回幂等成功。
240	        if (BatchStatus.SLAUGHTERED.name().equals(batch.status())) {
241	            return IdempotencyService.Outcome.ok(new SlaughterResponse(
242	                    batch.batchNo(), true, false, BatchStatus.SLAUGHTERED.name(),
243	                    earliest, null, batch.slaughteredAtUtc(), request.applyAtUtc()));
244	        }
245	
246	        boolean approved;
247	        String rejectReason = null;
248	        Instant slaughteredAt = null;
249	        if (earliest != null && request.applyAtUtc().isBefore(earliest)) {
250	            // 恰满休药天数当日 24:00 前申请，一律拒绝。
251	            approved = false;
252	            rejectReason = "休药期未满，拒绝出栏；最早合法出栏时刻(UTC)=" + earliest
253	                    + "（届满日 " + batch.withdrawalUntilDate() + " 当日 24:00 之后）";
254	        } else {
255	            approved = true;
256	        }
257	
258	        String status = BatchStatus.FEEDING.name();
259	        if (approved) {
260	            int updated = batchRepository.markSlaughteredIfFeeding(batch.id(), request.applyAtUtc());
261	            if (updated == 0) {
262	                throw ApiException.conflict("批次状态已被并发改变，请重新申请");
263	            }
264	            slaughteredAt = request.applyAtUtc();
265	            status = BatchStatus.SLAUGHTERED.name();
266	        }
267	
268	        SlaughterResponse response = new SlaughterResponse(
269	                batch.batchNo(), approved, false, status,
270	                earliest, rejectReason, slaughteredAt, request.applyAtUtc());
271	        // 休药期内拒绝为确定性的首次结果，以 422 落库，重放返回同一拒绝结果。
272	        return new IdempotencyService.Outcome(response, approved ? 200 : 422);
273	    }
274	
275	    /**
276	     * 按批次全部含药饲喂事件逐支复算合并休药期：
277	     * 最晚末次饲喂时刻 + 各药物最大休药天数（仅统计非迟到事件；迟到事件不影响已冻结义务）。
278	     */
279	    private Merged recomputeBatchWithdrawal(long batchId) {
280	        List<ProductionRepository.FeedingRow> feedings =
281	                productionRepository.findFeedingsByBatch(batchId);
282	        Instant latestFeed = null;
283	        int maxDays = 0;
284	        for (ProductionRepository.FeedingRow feeding : feedings) {
285	            if (feeding.late()) {
286	                continue;
287	            }
288	            List<ProductionRepository.DrugSnapshotRow> snapshots =
289	                    productionRepository.findSnapshots(feeding.productionId());
290	            int feedingMaxDays = snapshots.stream()
291	                    .mapToInt(ProductionRepository.DrugSnapshotRow::withdrawalDays)
292	                    .max().orElse(0);
293	            // 合并口径：各药物取最大休药天数；饲喂时刻取最晚一次。
294	            maxDays = Math.max(maxDays, feedingMaxDays);
295	            if (latestFeed == null || feeding.feedAtUtc().isAfter(latestFeed)) {
296	                latestFeed = feeding.feedAtUtc();
297	            }
298	        }
299	        if (latestFeed == null) {
300	            return null;
301	        }
302	        LocalDate untilDate = WithdrawalCalculator.withdrawalUntilDate(latestFeed, maxDays);
303	        return new Merged(latestFeed, maxDays, untilDate);
304	    }
305	
306	    private Instant earliest(LocalDate untilDate) {
307	        return untilDate == null ? null : WithdrawalCalculator.earliestSlaughter(untilDate);
308	    }
309	
310	    private BatchStatusResponse toStatusResponse(BatchRepository.BatchRow row) {
311	        return new BatchStatusResponse(
312	                row.batchNo(),
313	                row.species(),
314	                row.status(),
315	                row.lastMedicatedFeedAtUtc(),
316	                row.withdrawalUntilDate(),
317	                earliest(row.withdrawalUntilDate()),
318	                row.governingWithdrawalDays(),
319	                row.slaughteredAtUtc());
320	    }
321	
322	    /** 合并休药期中间结果。 */
323	    private record Merged(Instant latestFeed, int maxDays, LocalDate untilDate) {
324	    }
325	}
