1	package com.example.starter.feed.service;
2	
3	import com.example.starter.feed.repo.IdempotentRepository;
4	import com.example.starter.feed.web.ApiException;
5	import com.fasterxml.jackson.core.JsonProcessingException;
6	import com.fasterxml.jackson.databind.ObjectMapper;
7	import org.springframework.dao.DuplicateKeyException;
8	import org.springframework.jdbc.core.JdbcTemplate;
9	import org.springframework.stereotype.Service;
10	import org.springframework.transaction.annotation.Transactional;
11	
12	import java.util.function.Supplier;
13	
14	/**
15	 * requestId 幂等执行模板。
16	 *
17	 * <p>并发协议（同一事务内完成）：先向 idempotent_request 插入 PENDING 占位行占用 requestId，
18	 * 再执行业务写入并把首次响应 JSON 回填。若并发同键请求插入占位行时撞唯一约束，
19	 * 则阻塞至首请求事务结束后读取其最终响应：指纹相同回放（携带首次 HTTP 状态），
20	 * 指纹不同返回 409 且不改变状态。</p>
21	 */
22	@Service
23	public class IdempotencyService {
24	
25	    private static final String PENDING = "PENDING";
26	    private static final long AWAIT_TIMEOUT_MS = 5000;
27	
28	    private final JdbcTemplate jdbc;
29	    private final IdempotentRepository idempotentRepository;
30	    private final ObjectMapper objectMapper;
31	
32	    public IdempotencyService(JdbcTemplate jdbc,
33	                              IdempotentRepository idempotentRepository,
34	                              ObjectMapper objectMapper) {
35	        this.jdbc = jdbc;
36	        this.idempotentRepository = idempotentRepository;
37	        this.objectMapper = objectMapper;
38	    }
39	
40	    /**
41	     * 业务执行结果：响应对象与对应 HTTP 状态码（拒绝类决策也作为首次结果落库）。
42	     */
43	    public record Outcome(Object response, int httpStatus) {
44	        public static Outcome ok(Object response) {
45	            return new Outcome(response, 200);
46	        }
47	    }
48	
49	    /**
50	     * 幂等执行结果。
51	     *
52	     * @param response   响应体（首次或重放还原）
53	     * @param httpStatus 首次结果对应的 HTTP 状态
54	     * @param replayed   是否为同键同参重放
55	     */
56	    public record Result<T>(T response, int httpStatus, boolean replayed) {
57	    }
58	
59	    /**
60	     * 以 requestId 幂等执行业务回调。
61	     *
62	     * @param requestId 幂等键
63	     * @param kind      请求类型
64	     * @param payload   全部业务字段（指纹输入，含 requestId）
65	     * @param action    首次业务动作（在占位行事务内执行）
66	     * @param type      响应反序列化类型（重放时还原 JSON）
67	     */
68	    @Transactional
69	    public <T> Result<T> execute(String requestId, String kind, Object payload,
70	                                 Supplier<Outcome> action, Class<T> type) {
71	        String fingerprint = FingerprintUtil.sha256(payload);
72	
73	        var existing = idempotentRepository.find(requestId);
74	        if (existing.isPresent()) {
75	            return resolve(existing.get(), fingerprint, type);
76	        }
77	
78	        boolean acquired;
79	        try {
80	            jdbc.update("INSERT INTO idempotent_request (request_id, request_kind, fingerprint, http_status, response_json) "
81	                            + "VALUES (?,?,?,?,?)",
82	                    requestId, kind, fingerprint, 0, PENDING);
83	            acquired = true;
84	        } catch (DuplicateKeyException e) {
85	            acquired = false;
86	        }
87	
88	        if (!acquired) {
89	            // 并发首请求刚刚提交：读取最终结果（必要时短暂等待回填）。
90	            return resolve(awaitFinal(requestId), fingerprint, type);
91	        }
92	
93	        // 业务异常直接抛出，事务（含 PENDING 占位行）整体回滚，允许同键重试。
94	        Outcome outcome = action.get();
95	        jdbc.update("UPDATE idempotent_request SET http_status = ?, response_json = ? WHERE request_id = ?",
96	                outcome.httpStatus(), toJson(outcome.response()), requestId);
97	
98	        @SuppressWarnings("unchecked")
99	        T typed = (T) outcome.response();
100	        return new Result<>(typed, outcome.httpStatus(), false);
101	    }
102	
103	    private <T> Result<T> resolve(IdempotentRepository.IdempotentRow row, String fingerprint, Class<T> type) {
104	        if (!row.fingerprint().equals(fingerprint)) {
105	            throw ApiException.conflict("requestId=" + row.requestId()
106	                    + " 已存在但业务参数不一致（同键异参），拒绝执行且不改变状态");
107	        }
108	        if (PENDING.equals(row.responseJson())) {
109	            throw ApiException.conflict("requestId=" + row.requestId() + " 的首请求仍在处理中");
110	        }
111	        return new Result<>(fromJson(row.responseJson(), type), row.httpStatus(), true);
112	    }
113	
114	    private IdempotentRepository.IdempotentRow awaitFinal(String requestId) {
115	        long deadline = System.currentTimeMillis() + AWAIT_TIMEOUT_MS;
116	        while (true) {
117	            var row = idempotentRepository.find(requestId);
118	            if (row.isPresent() && !PENDING.equals(row.get().responseJson())) {
119	                return row.get();
120	            }
121	            if (System.currentTimeMillis() > deadline) {
122	                throw ApiException.conflict("requestId=" + requestId + " 首请求结果等待超时");
123	            }
124	            try {
125	                Thread.sleep(10);
126	            } catch (InterruptedException e) {
127	                Thread.currentThread().interrupt();
128	                throw ApiException.conflict("等待首请求结果被中断");
129	            }
130	        }
