288	
289	    @Test
290	    void concurrentProductionOfTwoMedicatedFormulasMergesWithdrawalUniquely() throws Exception {
291	        postJson("/api/formulas/submit",
292	                submitBody("REQ-CC-1", "F-ENRO", "SWINE", List.of(drug("DRG-ENRO", 0.02))))
293	                .andExpect(status().isOk());
294	        approve("F-ENRO", 1);
295	        postJson("/api/formulas/submit",
296	                submitBody("REQ-CC-2", "F-TYLO", "SWINE", List.of(drug("DRG-TYLO", 0.01))))
297	                .andExpect(status().isOk());
298	        approve("F-TYLO", 1);
299	        createBatch("B-MERGE", "SWINE");
300	
301	        ExecutorService pool = Executors.newFixedThreadPool(2);
302	        CountDownLatch start = new CountDownLatch(1);
303	        Future<?> f1 = pool.submit(() -> {
304	            start.await();
305	            produce("F-ENRO", 1, "B-MERGE", "2026-09-01T08:00:00Z");
306	            return null;
307	        });
308	        Future<?> f2 = pool.submit(() -> {
309	            start.await();
310	            produce("F-TYLO", 1, "B-MERGE", "2026-09-03T20:00:00Z");
311	            return null;
312	        });
313	        start.countDown();
314	        f1.get(30, TimeUnit.SECONDS);
315	        f2.get(30, TimeUnit.SECONDS);
316	        pool.shutdown();
317	
318	        JsonNode merged = batch("B-MERGE");
319	        // 合并口径唯一：最晚末次饲喂 09-03T20:00Z，最大休药天数 14，届满日 09-17，最早出栏 09-18T00:00Z。
320	        assertThat(merged.path("lastMedicatedFeedAtUtc").asText()).isEqualTo("2026-09-03T20:00:00Z");
321	        assertThat(merged.path("governingWithdrawalDays").asInt()).isEqualTo(14);
322	        assertThat(merged.path("withdrawalUntilDate").asText()).isEqualTo("2026-09-17");
323	        assertThat(merged.path("earliestSlaughterUtc").asText()).isEqualTo("2026-09-18T00:00:00Z");
324	
325	        Integer productions = jdbc.queryForObject(
326	                "SELECT COUNT(*) FROM production_record pr JOIN herd_batch b ON b.id = pr.batch_id "
327	                        + "WHERE b.batch_no = 'B-MERGE'", Integer.class);
328	        Integer snapshots = jdbc.queryForObject(
329	                "SELECT COUNT(*) FROM production_drug_snapshot s "
330	                        + "JOIN production_record p ON p.id = s.production_id "
331	                        + "JOIN herd_batch b ON b.id = p.batch_id WHERE b.batch_no = 'B-MERGE'", Integer.class);
332	        assertThat(productions).isEqualTo(2);
333	        assertThat(snapshots).isEqualTo(2);
334	    }
