374	    @Test
375	    void concurrentSameKeySameParamsProducesExactlyOneVersionAndOneReplay() throws Exception {
376	        Map<String, Object> body = submitBody("REQ-CONC-IDEM", "F-CIDEM", "CHICKEN",
377	                List.of(drug("DRG-AMOX", 0.02)));
378	        String payload = objectMapper.writeValueAsString(body);
379	
380	        ExecutorService pool = Executors.newFixedThreadPool(2);
381	        CountDownLatch start = new CountDownLatch(1);
382	        java.util.List<Future<MvcResult>> futures = new java.util.ArrayList<>();
383	        for (int i = 0; i < 2; i++) {
384	            futures.add(pool.submit(() -> {
385	                start.await();
386	                return mockMvc.perform(post("/api/formulas/submit")
387	                                .contentType("application/json").content(payload))
388	                        .andReturn();
389	            }));
390	        }
391	        start.countDown();
392	        int okCount = 0;
393	        int replayCount = 0;
394	        for (Future<MvcResult> f : futures) {
395	            MvcResult r = f.get(30, TimeUnit.SECONDS);
396	            assertThat(r.getResponse().getStatus()).isEqualTo(200);
397	            JsonNode json = objectMapper.readTree(r.getResponse().getContentAsString());
398	            assertThat(json.path("version").asInt()).isEqualTo(1);
399	            okCount++;
400	            if (json.path("replayed").asBoolean()) {
401	                replayCount++;
402	            }
403	        }
404	        pool.shutdown();
405	        assertThat(okCount).isEqualTo(2);
406	        assertThat(replayCount).isEqualTo(1);
407	
408	        Integer count = jdbc.queryForObject(
409	                "SELECT COUNT(*) FROM feed_formula WHERE formula_code = 'F-CIDEM'", Integer.class);
410	        assertThat(count).isEqualTo(1);
411	    }
