package com.example.starter.feed.repo;

import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.core.simple.SimpleJdbcInsert;
import org.springframework.stereotype.Repository;

import java.sql.Timestamp;
import java.time.Instant;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * 治疗性用药直报仓储。直报落库后由服务层在同一事务内触发批次休药期重算。
 */
@Repository
public class TreatmentReportRepository {

    private final JdbcTemplate jdbc;
    private final SimpleJdbcInsert reportInsert;

    public TreatmentReportRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
        this.reportInsert = new SimpleJdbcInsert(jdbc)
                .withTableName("treatment_report")
                .usingColumns("request_id", "batch_id", "administered_at_utc", "max_withdrawal_days",
                        "confirmer_a", "confirmer_b", "late", "fingerprint")
                .usingGeneratedKeyColumns("id");
    }

    /** treatment_report 行（仅重算所需字段）。 */
    public record TreatmentReportRow(
            long id,
            long batchId,
            Instant administeredAtUtc,
            int maxWithdrawalDays,
            boolean late
    ) {
    }

    private static final RowMapper<TreatmentReportRow> MAPPER = (rs, n) -> new TreatmentReportRow(
            rs.getLong("id"),
            rs.getLong("batch_id"),
            DictRepository.toInstant(rs.getTimestamp("administered_at_utc")),
            rs.getInt("max_withdrawal_days"),
            rs.getBoolean("late")
    );

    /**
     * 插入直报主记录；同一批次同一给药时刻重复直报触发唯一约束。
     *
     * @return 新直报主键；同批次同时刻已存在直报时返回空
     */
    public Optional<Long> insertReport(String requestId, long batchId, Instant administeredAtUtc,
                                       int maxWithdrawalDays, String confirmerA, String confirmerB,
                                       boolean late, String fingerprint) {
        Map<String, Object> params = new HashMap<>();
        params.put("request_id", requestId);
        params.put("batch_id", batchId);
        params.put("administered_at_utc", Timestamp.from(administeredAtUtc));
        params.put("max_withdrawal_days", maxWithdrawalDays);
        params.put("confirmer_a", confirmerA);
        params.put("confirmer_b", confirmerB);
        params.put("late", late);
        params.put("fingerprint", fingerprint);
        try {
            return Optional.of(reportInsert.executeAndReturnKey(params).longValue());
        } catch (DuplicateKeyException e) {
            return Optional.empty();
        }
    }

    public void insertDrug(long reportId, String drugCode, String drugName, int withdrawalDays) {
        jdbc.update("INSERT INTO treatment_report_drug (report_id, drug_code, drug_name, withdrawal_days) "
                        + "VALUES (?,?,?,?)",
                reportId, drugCode, drugName, withdrawalDays);
    }

    /**
     * 取批次全部直报（重算时仅统计非迟到记录；迟到记录不影响已冻结义务）。
     */
    public List<TreatmentReportRow> findByBatch(long batchId) {
        return jdbc.query("SELECT * FROM treatment_report WHERE batch_id = ? ORDER BY id",
                MAPPER, batchId);
    }
}

package com.example.starter.feed.repo;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.core.simple.SimpleJdbcInsert;
import org.springframework.stereotype.Repository;

import java.sql.Timestamp;
import java.time.Instant;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * 出栏申请台账仓储。申请（批准预约/已核销/拒绝）逐条落账；
 * 治疗直报重算后在同一事务内自动撤销与新最早出栏日冲突的已批准预约，撤销记录保留可查。
 */
@Repository
public class SlaughterApplicationRepository {

    private final JdbcTemplate jdbc;
    private final SimpleJdbcInsert applicationInsert;

    public SlaughterApplicationRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
        this.applicationInsert = new SimpleJdbcInsert(jdbc)
                .withTableName("slaughter_application")
                .usingColumns("request_id", "batch_id", "apply_at_utc", "approved", "status", "reject_reason")
                .usingGeneratedKeyColumns("id");
    }

    /** slaughter_application 行。 */
    public record SlaughterApplicationRow(
            long id,
            String requestId,
            long batchId,
            Instant applyAtUtc,
            boolean approved,
            String status,
            String rejectReason,
            Instant revokedAtUtc,
            String revokeReason
    ) {
    }

    private static final RowMapper<SlaughterApplicationRow> MAPPER = (rs, n) -> new SlaughterApplicationRow(
            rs.getLong("id"),
            rs.getString("request_id"),
            rs.getLong("batch_id"),
            DictRepository.toInstant(rs.getTimestamp("apply_at_utc")),
            rs.getBoolean("approved"),
            rs.getString("status"),
            rs.getString("reject_reason"),
            DictRepository.toInstant(rs.getTimestamp("revoked_at_utc")),
            rs.getString("revoke_reason")
    );

    /**
     * 落账一条出栏申请。
     *
     * @return 新申请主键
     */
    public long insert(String requestId, long batchId, Instant applyAtUtc,
                       boolean approved, String status, String rejectReason) {
        Map<String, Object> params = new HashMap<>();
        params.put("request_id", requestId);
        params.put("batch_id", batchId);
        params.put("apply_at_utc", Timestamp.from(applyAtUtc));
        params.put("approved", approved);
        params.put("status", status);
        params.put("reject_reason", rejectReason);
        return applicationInsert.executeAndReturnKey(params).longValue();
    }

    /**
     * 自动撤销与新最早合法出栏时刻冲突的已批准预约（SCHEDULED 且申请时刻早于新最早出栏时刻）。
     * 与休药期重算在同一事务内完成，撤销记录保留可查。
     *
     * @return 被撤销的申请主键列表（升序）
     */
    public List<Long> revokeConflicting(long batchId, Instant newEarliestSlaughterUtc,
                                        Instant revokedAtUtc, String revokeReason) {
        List<Long> ids = jdbc.query(
                "SELECT id FROM slaughter_application WHERE batch_id = ? AND status = 'SCHEDULED' "
                        + "AND apply_at_utc < ? ORDER BY id",
                (rs, n) -> rs.getLong("id"), batchId, Timestamp.from(newEarliestSlaughterUtc));
        for (Long id : ids) {
            jdbc.update("UPDATE slaughter_application SET status = 'REVOKED', revoked_at_utc = ?, "
                            + "revoke_reason = ? WHERE id = ? AND status = 'SCHEDULED'",
                    Timestamp.from(revokedAtUtc), revokeReason, id);
        }
        return ids;
    }

    /**
     * 查询批次全部出栏申请台账（含撤销记录），按主键升序。
     */
    public List<SlaughterApplicationRow> findByBatch(long batchId) {
        return jdbc.query("SELECT * FROM slaughter_application WHERE batch_id = ? ORDER BY id",
                MAPPER, batchId);
    }
}

